// Clean-room TSVC s233/s2233 profiles; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s233_s2233_matrix_prefix(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<14||length>194{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];let mode=v[1];if !(2..=8).contains(&nr)||(mode!=0&&mode!=1){return -1;}let n=nr as usize;let nn=n*n;if length!=2+3*nn{return -1;}let mut a=[0i64;64];let mut b=[0i64;64];let mut c=[0i64;64];for i in 0..nn{let x=v[2+i];let y=v[2+nn+i];let z=v[2+2*nn+i];if !(-1..=1).contains(&x)||!(-1..=1).contains(&y)||!(-1..=1).contains(&z){return -1;}a[i]=x;b[i]=y;c[i]=z;}if output.is_null()||capacity<16*nn{return -2;}for i in 1..n{for j in 1..n{a[j*n+i]=a[(j-1)*n+i]+c[j*n+i];}}if mode==0{for i in 1..n{for j in 1..n{b[j*n+i]=b[j*n+i-1]+c[j*n+i];}}}else{for i in 1..n{for j in 1..n{b[i*n+j]=b[(i-1)*n+j]+c[i*n+j];}}}for i in 0..nn{for (k,val) in [a[i],b[i]].iter().enumerate(){let bits=*val as u64;let base=8*(k*nn+i);for j in 0..8{output.add(base+j).write((bits>>(8*j))as u8);}}}2*nn as i64}
